begin;
create extension if not exists pgtap with schema extensions;
select plan(12);
insert into auth.users(id,email) values ('10000000-0000-4000-8000-000000000008','text-answer@test.invalid');
insert into public.workspaces(id,name) values ('20000000-0000-4000-8000-000000000008','Text answer test');
insert into public.workspace_members values ('20000000-0000-4000-8000-000000000008','10000000-0000-4000-8000-000000000008','owner',now());
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000008","role":"authenticated"}',true);
create temporary table ids(result jsonb);
insert into ids values(public.save_case_revision('20000000-0000-4000-8000-000000000008','{"title":"Canary","template":"product_delivery","outcome":"achieved","problem":"Canary","context":"Team","constraints":"No downtime","approach":"Canary","observedOutcome":"Released","lessons":"Monitor","deliverable":"Feature","changeScope":"Checkout","deploymentConditions":"Rollback","sources":[],"conceptIds":[]}'));
select public.publish_case_revision((select (result->>'revisionId')::uuid from ids),(select jsonb_agg(jsonb_build_object('key',key,'text',value,'embedding',to_jsonb(array_prepend(1::float8,array_fill(0::float8,array[1535]))))) from public.case_revisions,jsonb_each_text(content) where workspace_id='20000000-0000-4000-8000-000000000008' and key in ('problem','context','constraints','approach','observedOutcome','lessons','deliverable','changeScope','deploymentConditions')),'gemini-embedding-2',1536);
create temporary table snapshots as select value as item from public.read_knowledge_case('20000000-0000-4000-8000-000000000008',(select (result->>'caseId')::uuid from ids),(select (result->>'revisionId')::uuid from ids),array['approach'],1) value;
create temporary table runs(result jsonb);
insert into runs values(public.admit_analysis('20000000-0000-4000-8000-000000000008','{"version":2,"message":"How can we release?","history":[]}',gen_random_uuid(),2,300000));
select is((select deadline_at-created_at from public.analysis_runs where id=(select (result->>'runId')::uuid from runs)),interval '300 seconds','admission preserves the selected duration');
select is((select request->>'message' from public.analysis_runs where id=(select (result->>'runId')::uuid from runs)),'How can we release?','raw question is stored');
select throws_ok($$select public.finish_analysis((select (result->>'runId')::uuid from runs),'complete',jsonb_build_object('version',2,'text','Old [S:00000000-0000-4000-8000-000000000001:1]','citations',jsonb_build_array(jsonb_build_object('marker','[S:00000000-0000-4000-8000-000000000001:1]','evidenceId',(select item->>'evidenceId' from snapshots)))),(select jsonb_agg(item) from snapshots),'',null)$$,'P0001','Invalid citation','a marker from another run is rejected');
select throws_ok($$select public.finish_analysis((select (result->>'runId')::uuid from runs),'complete',jsonb_build_object('version',2,'text','Use the canary [S:'||(select result->>'runId' from runs)||':1]','citations',jsonb_build_array(jsonb_build_object('marker','[S:'||(select result->>'runId' from runs)||':1]','evidenceId',(select item->>'evidenceId' from snapshots)))),(select jsonb_build_array(jsonb_set(item,'{outcome}','"unknown"')) from snapshots),'',null)$$,'P0001','Invalid evidence','forged source metadata is rejected');
select throws_ok($$select public.finish_analysis((select (result->>'runId')::uuid from runs),'complete',jsonb_build_object('version',2,'text','Use it [S:'||(select result->>'runId' from runs)||':1] and [S:'||(select result->>'runId' from runs)||':2]','citations',jsonb_build_array(jsonb_build_object('marker','[S:'||(select result->>'runId' from runs)||':1]','evidenceId',(select item->>'evidenceId' from snapshots)))),(select jsonb_agg(item) from snapshots),'',null)$$,'P0001','Invalid citation','unmapped marker is rejected');
select public.finish_analysis((select (result->>'runId')::uuid from runs),'complete',jsonb_build_object('version',2,'text','Use the canary [S:'||(select result->>'runId' from runs)||':1]','citations',jsonb_build_array(jsonb_build_object('marker','[S:'||(select result->>'runId' from runs)||':1]','evidenceId',(select item->>'evidenceId' from snapshots)))),(select jsonb_agg(item) from snapshots),'',null);
select is((select generated->>'text' from public.briefs where run_id=(select (result->>'runId')::uuid from runs)),'Use the canary [S:'||(select result->>'runId' from runs)||':1]','valid answer is saved');
select is((select hard_constraints from public.briefs where run_id=(select (result->>'runId')::uuid from runs)),'[]'::jsonb,'text input does not invent structured constraints');
select is((select evidence->0->>'excerpt' from public.briefs where run_id=(select (result->>'runId')::uuid from runs)),'Canary','exact authorized source snapshot is saved');
create temporary table late_run(result jsonb);
insert into late_run values(public.admit_analysis('20000000-0000-4000-8000-000000000008','{"version":2,"message":"Late answer","history":[]}',gen_random_uuid(),2,1));
select pg_sleep(0.05);
select is(public.finish_analysis((select (result->>'runId')::uuid from late_run),'complete','{"version":2,"text":"Late","citations":[]}'::jsonb,'[]'::jsonb,'',null),null::uuid,'an answer completed after the deadline is not saved');
select is((select status from public.analysis_runs where id=(select (result->>'runId')::uuid from late_run)),'timed_out','deadline uses the current time even within a long transaction');
select throws_ok($$select public.admit_analysis('20000000-0000-4000-8000-000000000008','{"version":2,"message":"Expired","history":[]}',gen_random_uuid(),2,300000,clock_timestamp()-interval '1 second')$$,'22023','Admission deadline elapsed','expired hosted cutoff is rejected');
create temporary table hosted_run(result jsonb, cutoff timestamptz);
insert into hosted_run select public.admit_analysis('20000000-0000-4000-8000-000000000008','{"version":2,"message":"Hosted","history":[]}',gen_random_uuid(),2,300000,now()+interval '120 seconds'),now()+interval '120 seconds';
select ok((select deadline_at<=cutoff from public.analysis_runs,hosted_run where id=(result->>'runId')::uuid),'persisted deadline does not exceed the hosted cutoff');
select * from finish();
rollback;
